import{_ as n,o as t,c as s,a2 as l}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"7. 联盟","description":"","frontmatter":{},"headers":[],"relativePath":"union.md","filePath":"union.md"}'),e={name:"union.md"};function i(p,a,d,o,c,r){return t(),s("div",null,[...a[0]||(a[0]=[l(`<h1 id="_7-联盟" tabindex="-1">7. 联盟 <a class="header-anchor" href="#_7-联盟" aria-label="Permalink to &quot;7. 联盟&quot;">​</a></h1><h2 id="_7-1-基本规则" tabindex="-1">7.1 基本规则 <a class="header-anchor" href="#_7-1-基本规则" aria-label="Permalink to &quot;7.1 基本规则&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>规则</th></tr></thead><tbody><tr><td>创建费用</td><td><strong>64 钻石</strong>（从创建者余额扣，不进入联盟金库）</td></tr><tr><td>联盟名长度</td><td>2–24 字符</td></tr><tr><td>允许字符</td><td>中文、字母、数字、下划线</td></tr><tr><td>创建确认</td><td>5 秒内 <code>/union confirm</code></td></tr><tr><td>邀请有效期</td><td>10 分钟</td></tr><tr><td>申请有效期</td><td>7 天</td></tr><tr><td>当前联盟等级</td><td><strong>固定 Lv.1</strong></td></tr><tr><td>Lv.1 人数上限</td><td><strong>10 人</strong></td></tr><tr><td>Lv.1 免费领地额度</td><td><strong>1,024 格</strong></td></tr></tbody></table><blockquote><p>重要：虽然设计了 2–10 级的升级曲线，但当前版本<strong>没有任何玩法会给予联盟经验</strong>，所以所有联盟都停留在 Lv.1。不要按旧文档的“等级表”规划人数或领地；想扩容只能花钻石购买。</p></blockquote><h2 id="_7-2-创建与加入" tabindex="-1">7.2 创建与加入 <a class="header-anchor" href="#_7-2-创建与加入" aria-label="Permalink to &quot;7.2 创建与加入&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/union create &lt;名字&gt;            创建联盟（64 钻石，5 秒内确认）</span></span>
<span class="line"><span>/union confirm                  确认创建/解散等操作</span></span>
<span class="line"><span>/union invite &lt;玩家&gt;            邀请玩家</span></span>
<span class="line"><span>/union accept &lt;联盟编号&gt;        接受邀请（编号见邀请提示/联盟列表）</span></span>
<span class="line"><span>/union join &lt;联盟编号&gt; [留言]   主动申请加入（/union apply 为兼容别名）</span></span>
<span class="line"><span>/union audit                    打开入盟申请审核界面</span></span>
<span class="line"><span>/union info [联盟编号]          查看联盟信息</span></span>
<span class="line"><span>/union list                     查看联盟列表与编号</span></span></code></pre></div><ul><li>邀请 10 分钟内有效。</li><li>主动申请 7 天内有效，盟主/有权限的职位在 <code>/union audit</code> 里处理。</li><li>退出或被踢后重新加入没有额外冷却。</li></ul><h2 id="_7-3-职位与权限" tabindex="-1">7.3 职位与权限 <a class="header-anchor" href="#_7-3-职位与权限" aria-label="Permalink to &quot;7.3 职位与权限&quot;">​</a></h2><p>新建联盟默认有两个职位：</p><table tabindex="0"><thead><tr><th>职位</th><th>默认权限</th></tr></thead><tbody><tr><td>盟主</td><td>管理成员、创建/管理联盟领地、设置旗标、购买额度、管理金库</td></tr><tr><td>成员</td><td>进入联盟领地、建造、使用容器、骑乘、传送</td></tr></tbody></table><p>盟主可以用 <code>/union rank</code> 打开职位管理界面，自建职位并分配权限。默认成员在联盟领地内可以建造和使用容器；如果不想让所有成员都能动，需调整职位权限。</p><p>同联盟成员之间默认不能互相攻击（服务器固定开启），盟主不能通过职位关闭；该保护只对联盟内成员生效。</p><h2 id="_7-4-联盟金库" tabindex="-1">7.4 联盟金库 <a class="header-anchor" href="#_7-4-联盟金库" aria-label="Permalink to &quot;7.4 联盟金库&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/union account                  打开金库界面</span></span>
<span class="line"><span>/union account balance          查看余额</span></span>
<span class="line"><span>/union account deposit &lt;金额&gt;   从个人余额存入</span></span>
<span class="line"><span>/union account withdraw &lt;金额&gt;  从金库取到个人余额（需取款权限）</span></span>
<span class="line"><span>/union account log              查看流水</span></span></code></pre></div><ul><li>金库是独立的联盟资金，不属于任何个人。</li><li>创建联盟的 64 钻石<strong>不会</strong>进入金库。</li><li>联盟领地扩容从金库扣款。</li><li>取款权限由职位控制；默认盟主可操作。</li></ul><h2 id="_7-5-联盟聊天" tabindex="-1">7.5 联盟聊天 <a class="header-anchor" href="#_7-5-联盟聊天" aria-label="Permalink to &quot;7.5 联盟聊天&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/union chat &lt;消息&gt;</span></span></code></pre></div><p>也可以 <code>/channel Union</code> 切换到联盟频道，再直接发言。联盟频道只有同联盟成员可见。</p><h2 id="_7-6-联盟领地-gclaim" tabindex="-1">7.6 联盟领地（<code>/gclaim</code>） <a class="header-anchor" href="#_7-6-联盟领地-gclaim" aria-label="Permalink to &quot;7.6 联盟领地（\`/gclaim\`）&quot;">​</a></h2><p>联盟领地与个人领地是两套系统，命令前缀不同。</p><table tabindex="0"><thead><tr><th>项目</th><th>规则</th></tr></thead><tbody><tr><td>初始额度</td><td>1,024 格（Lv.1）</td></tr><tr><td>每级增加</td><td>+512 格（当前等级不增长）</td></tr><tr><td>额度上限</td><td>4,096 格</td></tr><tr><td>购买价格</td><td><strong>当前实际 100 钻石/格</strong>（标价 1，见 5.4 价格提示），从联盟金库扣</td></tr><tr><td>领地数量</td><td>不限（只受总面积限制）</td></tr><tr><td>最小边长</td><td>3 格</td></tr><tr><td>最大边长</td><td>128 格</td></tr><tr><td>最大长宽比</td><td>8:1</td></tr><tr><td>子领地</td><td>每块主领地最多 10 块，仅一层</td></tr><tr><td>子领地边长</td><td>3–64 格</td></tr><tr><td>与其他联盟领地间距</td><td>至少 8 格</td></tr><tr><td>主城保护</td><td>主城全境不可圈地（服务器保护区）</td></tr><tr><td>出生点保护</td><td>每个世界出生点 100 格内不能完整圈地</td></tr></tbody></table><p>常用命令：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/gclaim                        打开联盟领地界面</span></span>
<span class="line"><span>/gclaim create &lt;名字&gt;          用金锄选区后创建</span></span>
<span class="line"><span>/gclaim info [领地]            查看信息</span></span>
<span class="line"><span>/gclaim list                   列出联盟领地</span></span>
<span class="line"><span>/gclaim quota                  查看额度</span></span>
<span class="line"><span>/gclaim buy &lt;格数&gt;             用联盟金库购买额度</span></span>
<span class="line"><span>/gclaim expand &lt;格数&gt; [方向]   扩边</span></span>
<span class="line"><span>/gclaim resize &lt;领地&gt;          重新选区后应用</span></span>
<span class="line"><span>/gclaim tp                     传送到联盟领地</span></span>
<span class="line"><span>/gclaim settp                  设置联盟领地传送点</span></span>
<span class="line"><span>/gclaim flag &lt;领地&gt; &lt;旗标&gt; &lt;值&gt; 设置旗标</span></span>
<span class="line"><span>/gclaim perms &lt;领地&gt;          查看领地权限</span></span>
<span class="line"><span>/gclaim perm &lt;领地&gt; &lt;职位&gt; &lt;旗标&gt; &lt;值&gt;</span></span>
<span class="line"><span>                              设置职位权限</span></span>
<span class="line"><span>/gclaim ban &lt;玩家&gt; [领地]      封禁</span></span>
<span class="line"><span>/gclaim unban &lt;玩家&gt; [领地]    解封</span></span>
<span class="line"><span>/gclaim sub create &lt;名字&gt;      创建子领地</span></span>
<span class="line"><span>/gclaim map / borders          地图、边界显示</span></span>
<span class="line"><span>/gclaim delete &lt;领地&gt;          删除</span></span></code></pre></div><p>说明：</p><ul><li>联盟领地创建/管理需要盟主或对应职位权限；普通成员主要是在领地内建造、使用容器和传送。</li><li>联盟领地没有自动创建命令；必须先用金锄选区，再 <code>/gclaim create &lt;名字&gt;</code>。</li><li>单边 128 是硬上限，但面积上限 4,096 会先触发；实际形状通常不超过 64×64 的正方形，只有狭长形状才可能用到 128 边。</li><li>购买额度当前实际 100 钻石/格（标价 1 钻石/格，见 5.4 价格提示），通常先用免费额度。</li><li>子领地只有一层，不能嵌套；每块主领地上限 10 块。</li><li>联盟领地与个人领地不能重叠。</li></ul><h2 id="_7-7-成员管理" tabindex="-1">7.7 成员管理 <a class="header-anchor" href="#_7-7-成员管理" aria-label="Permalink to &quot;7.7 成员管理&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/union kick &lt;玩家&gt;            踢出成员</span></span>
<span class="line"><span>/union ban &lt;玩家&gt; [原因]      封禁成员</span></span>
<span class="line"><span>/union unban &lt;玩家&gt;           解除封禁</span></span>
<span class="line"><span>/union transfer &lt;玩家&gt;        转让盟主</span></span>
<span class="line"><span>/union leave                  退出联盟</span></span>
<span class="line"><span>/union disband                解散联盟</span></span>
<span class="line"><span>/union rename &lt;新名&gt;        改名</span></span>
<span class="line"><span>/union rank                   职位管理</span></span></code></pre></div><p><code>/union leave</code>、<code>/union disband</code> 等操作需要二次确认；按提示在 5 秒内输入 <code>/union confirm</code>。</p>`,28)])])}const h=n(e,[["render",i]]);export{u as __pageData,h as default};
